def run(df):
    # Verify required columns exist
    required = ['Churn', 'SatisfactionScore']
    missing = [c for c in required if c not in df.columns]
    if missing:
        return (f"Missing column(s): {', '.join(missing)}.", None)

    # Keep only rows where churned and satisfaction score is not null
    churned = df[(df['Churn'] == 'Yes')].dropna(subset=['SatisfactionScore'])

    if churned.empty:
        return ("No churned customers with a recorded SatisfactionScore.", None)

    median_score = churned['SatisfactionScore'].median()
    result = f"Median SatisfactionScore for churned customers: {median_score:.2f}"
    return (result, None)
```
This computes the median satisfaction score for customers whose **Churn** value is “Yes”, ignoring missing scores.

