def run(df):
    # Verify required columns are present
    missing = [c for c in ['Discount', 'Profit'] if c not in df.columns]
    if missing:
        return (f"Missing column(s): {', '.join(missing)}.", None)

    # Drop rows where either column is NaN so the two series stay aligned
    data = df.dropna(subset=['Discount', 'Profit'])
    if len(data) < 3:
        return ("Not enough non‑missing rows to compute a correlation.", None)

    # Pearson correlation
    r, p = scipy_stats.pearsonr(data['Discount'], data['Profit'])

    # Build a scatter plot with a linear trendline (plotly)
    fig = px.scatter(
        data,
        x='Discount',
        y='Profit',
        trendline='ols',
        title=f'Discount vs Profit (Pearson r = {r:.3f})',
        labels={'Discount': 'Discount', 'Profit': 'Profit'}
    )

    # Human‑readable summary
    significance = 'statistically significant' if p < 0.05 else 'not statistically significant'
    result = (
        f"Pearson correlation r = {r:.3f} (p = {p:.4f}) — {significance} "
        f"based on {len(data):,} rows with non‑missing values."
    )
    return (result, fig)
```
The function drops missing values, computes Pearson r and p‑value, and returns a scatter plot with an OLS trendline.

